#!/usr/bin/env bash
# Renders a .x model with BlitzLLVM and with the original Blitz3D 1.118 (under Wine, see tools/original_blitz3d.md) and puts the two
# pictures and the two reports (tests/x_compare/xview.bb) next to each other, for functional comparisons only.
# Usage: tools/x_compare.sh <model.x> <name> [animation time, default -1 for none]
# BLITZCC defaults to build/code_compiler/blitzcc. Output: /tmp/x_compare/<name>/{orig,ours}.{txt,bmp}
# AUTOGENERATED COPYRIGHT HEADER START
# Copyright (C) 2026 Claude <noreply@anthropic.com>
# AUTOGENERATED COPYRIGHT HEADER END
set -eu
here="$(cd "$(dirname "$0")/.." && pwd)"
model="$(realpath "$1")"; name="$2"; time="${3:--1}"
blitzcc="${BLITZCC:-$here/build/code_compiler/blitzcc}"
out="/tmp/x_compare/$name"
mkdir -p "$out"
dir="$(dirname "$model")"
for who in orig ours; do
	# The program is next to the model so that its textures are found where the model says.
	prog="$dir/xview_${name}_$who.bb"
	sed -e "s#@MODEL@#$(basename "$model")#" -e "s#@NAME@#${who}_$name#" -e "s#@TIME@#$time#" "$here/tests/x_compare/xview.bb" >"$prog"
done
"$here/tools/original_blitz3d.sh" run "$dir/xview_${name}_orig.bb" 120 || true
(cd "$dir" && xvfb-run -a "$blitzcc" -q "xview_${name}_ours.bb" 2>&1 | tail -3) || true
mv -f "$dir/orig_$name".{txt,bmp} "$out/" 2>/dev/null || true
mv -f "$dir/ours_$name".{txt,bmp} "$out/" 2>/dev/null || true
rm -f "$dir/xview_${name}_"*.bb "$dir/xview_${name}_orig.exe"
ls -la "$out"
